  page.on('response', (res) => { if (res.status() >= 500) networkErrors.push(`${res.status()} ${res.url()}`); });
  try {
  await test.step("Step 0: go to https://todomvc.com/examples/react/dist/", async () => {
    await page.goto("https://todomvc.com/examples/react/dist/");
  });

  await test.step("Step 1: fill \"What needs to be done?\" with \"Buy milk\"", async () => {
    const el1 = page.getByPlaceholder('What needs to be done?');
    await el1.first().fill("Buy milk");
  });

  await test.step("Step 2: press Enter", async () => {
    await page.keyboard.press("Enter");
  });

  await test.step("Step 3: fill \"What needs to be done?\" with \"Walk the dog\"", async () => {
    const el2 = page.getByPlaceholder('What needs to be done?');
    await el2.first().fill("Walk the dog");
  });

  await test.step("Step 4: press Enter", async () => {
    await page.keyboard.press("Enter");
  });

  await test.step("Step 5: expect \"2 items left\" to be visible", async () => {
    const assert3 = page.getByText('2 items left');
    await expect(assert3.first()).toBeVisible();
  });
  } finally {
    await testInfo.attach('console-errors.json', { body: Buffer.from(JSON.stringify(consoleErrors)), contentType: 'application/json' });
    await testInfo.attach('network-errors.json', { body: Buffer.from(JSON.stringify(networkErrors)), contentType: 'application/json' });
  }
